var moves = $json.result || [];
if (moves.length === 0) return [];

// Extraer pares únicos product_id + location real
var pares = {};
for (var i = 0; i < moves.length; i++) {
  var m = moves[i];
  var pid = m.product_id ? m.product_id[0] : null;
  // La ubicación real es la que NO es 68 (virtual)
  var locId = (m.location_dest_id && m.location_dest_id[0] === 68)
    ? (m.location_id ? m.location_id[0] : null)
    : (m.location_dest_id ? m.location_dest_id[0] : null);
  if (pid && locId) {
    pares[pid + '_' + locId] = { pid: pid, locId: locId };
  }
}

var productIds = [];
var locationIds = [];
Object.values(pares).forEach(function(p) {
  if (productIds.indexOf(p.pid) === -1) productIds.push(p.pid);
  if (locationIds.indexOf(p.locId) === -1) locationIds.push(p.locId);
});

return [{ json: {
  moves: moves,
  productIds: productIds,
  locationIds: locationIds
} }];

