var quants = $json.result || [];
var moves = $('Extraer Productos y Ubicaciones').first().json.moves || [];
var params = $('Calcular Ventana de Tiempo').first().json;

// Mapa de stock actual: 'productId_locationId' -> quantity
var stockMap = {};
for (var i = 0; i < quants.length; i++) {
  var q = quants[i];
  var pid = q.product_id ? q.product_id[0] : null;
  var lid = q.location_id ? q.location_id[0] : null;
  if (pid && lid) stockMap[pid + '_' + lid] = q.quantity || 0;
}

// Agrupar movimientos por fecha (minuto) + empresa
var grupos = {};
for (var j = 0; j < moves.length; j++) {
  var m = moves[j];
  var fechaMin = (m.date || '').substring(0, 16);
  var empresa = m.company_id ? m.company_id[1] : 'Sin empresa';
  var key = fechaMin + '||' + empresa;
  if (!grupos[key]) grupos[key] = { fecha: fechaMin, empresa: empresa, movs: [] };
  grupos[key].movs.push(m);
}

var totalMovs = moves.length;
var totalAjustes = Object.keys(grupos).length;

var filas = '';
var bgToggle = false;

Object.keys(grupos).sort().reverse().forEach(function(key) {
  var g = grupos[key];
  g.movs.forEach(function(m, idx) {
    var pid = m.product_id ? m.product_id[0] : null;
    var esReduccion = m.location_dest_id && m.location_dest_id[0] === 68;
    // Ubicación real del producto (la que no es virtual)
    var locReal = esReduccion
      ? (m.location_id ? m.location_id[0] : null)
      : (m.location_dest_id ? m.location_dest_id[0] : null);
    var locNombre = esReduccion
      ? (m.location_id ? m.location_id[1] : '')
      : (m.location_dest_id ? m.location_dest_id[1] : '');

    var stockActual = (pid && locReal) ? (stockMap[pid + '_' + locReal] || 0) : 0;
    var movQty = parseFloat(m.quantity) || 0;

    // Calcular antes y después
    var despues = stockActual;
    var antes = esReduccion ? stockActual + movQty : stockActual - movQty;
    var diff = despues - antes; // negativo = bajó, positivo = subió
    var diffStr = (diff >= 0 ? '+' : '') + diff.toFixed(2);
    var diffColor = diff < 0 ? '#dc3545' : diff > 0 ? '#28a745' : '#6c757d';
    var tipoIcono = esReduccion ? '🔻' : '🔺';
    var tipoBg = esReduccion ? '#fff5f5' : '#f0fff4';

    var producto = m.product_id ? m.product_id[1] : 'N/A';
    var bg = idx % 2 === 0 ? '#ffffff' : '#f8f9fa';

    if (idx === 0) {
      filas += '<tr style="background:' + bg + '">';
      filas += '<td rowspan="' + g.movs.length + '" style="padding:8px 10px;border:1px solid #dee2e6;vertical-align:top;font-weight:600;white-space:nowrap;font-size:12px;">' + g.fecha.replace('T',' ') + '</td>';
      filas += '<td rowspan="' + g.movs.length + '" style="padding:8px 10px;border:1px solid #dee2e6;vertical-align:top;font-size:12px;color:#555;">' + g.empresa + '</td>';
    } else {
      filas += '<tr style="background:' + bg + '">';
    }

    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;font-size:12px;">' + producto + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;font-size:12px;color:#555;">' + locNombre + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;text-align:center;font-size:13px;">' + antes.toFixed(2) + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;text-align:center;font-size:13px;">' + despues.toFixed(2) + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;text-align:center;font-weight:700;color:' + diffColor + ';">' + tipoIcono + ' ' + diffStr + '</td>';
    filas += '</tr>';

    bgToggle = !bgToggle;
  });
});

var tabla = '<table style="width:100%;border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px;">' +
  '<thead>' +
  '<tr style="background:#0066CC;color:#fff;">' +
  '<th style="padding:10px;text-align:left;">Fecha</th>' +
  '<th style="padding:10px;text-align:left;">Empresa</th>' +
  '<th style="padding:10px;text-align:left;">Producto</th>' +
  '<th style="padding:10px;text-align:left;">Ubicación</th>' +
  '<th style="padding:10px;text-align:center;">Stock Antes</th>' +
  '<th style="padding:10px;text-align:center;">Stock Después</th>' +
  '<th style="padding:10px;text-align:center;">Diferencia</th>' +
  '</tr>' +
  '</thead>' +
  '<tbody>' + filas + '</tbody>' +
  '</table>';

return [{ json: {
  tabla: tabla,
  totalMovs: totalMovs,
  totalAjustes: totalAjustes,
  now_label: params.now_label
} }];
